export interface AccordionProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange"> {
  /** Allow multiple panels open at once. */
  type?: "single" | "multiple";
  /** Initial open value(s). */
  defaultValue?: string | string[];
}

export interface AccordionItemProps extends React.HTMLAttributes<HTMLDivElement> {
  value: string;
}

export interface ActionConfirmationProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  /** The action in question, e.g. `"Send 18 emails?"`. */
  title: React.ReactNode;
  /** What will happen / why it matters. */
  description?: React.ReactNode;
  /** Risk styling. `destructive` for irreversible/high-impact actions. */
  variant?: ActionConfirmationVariant;
  /** Badge text marking this as an agent action. Defaults to `"AI action"`. */
  badge?: React.ReactNode;
  /** Leading icon. Defaults to a warning triangle. */
  icon?: React.ReactNode;
  confirmLabel?: React.ReactNode;
  cancelLabel?: React.ReactNode;
  onConfirm?: () => void;
  onCancel?: () => void;
}

export interface ActionPlanStepProps
  extends Omit<React.LiHTMLAttributes<HTMLLIElement>, "title"> {
  /** Step title. */
  title: React.ReactNode;
  /** Supporting detail under the title. */
  description?: React.ReactNode;
}

export interface ActionPlanProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Heading, e.g. `"Proposed plan"`. */
  heading?: React.ReactNode;
  /** Short description of what the agent intends to do. */
  description?: React.ReactNode;
  /** Called when the plan is accepted. Renders the accept button when set. */
  onAccept?: () => void;
  /** Called when the user asks to edit the plan. Renders the edit button when set. */
  onEdit?: () => void;
  /** Called when the plan is rejected. Renders the reject button when set. */
  onReject?: () => void;
  acceptLabel?: React.ReactNode;
  editLabel?: React.ReactNode;
  rejectLabel?: React.ReactNode;
}

export interface ActionTileProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "title"> {
  /** Icon shown in the accent container at the top of the tile. */
  icon: React.ReactNode;
  /** Tile title. */
  title: React.ReactNode;
  /** Supporting description below the title. */
  description?: React.ReactNode;
}

export interface ActivityLogItemProps extends React.LiHTMLAttributes<HTMLLIElement> {
  /** Icon for the action type. Defaults to a generic activity glyph. */
  icon?: React.ReactNode;
  /** Relative or absolute timestamp, e.g. `"2m ago"`. */
  time?: React.ReactNode;
}

export interface ActivityLogProps extends React.HTMLAttributes<HTMLOListElement> {
  /** Heading above the trail. */
  heading?: React.ReactNode;
}

export interface AgentComposerProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onSubmit"> {
  /** Controlled textarea value. */
  value: string;
  onValueChange: (value: string) => void;
  /** Called with the trimmed value on submit (Enter or send). */
  onSubmit: (value: string) => void;
  placeholder?: string;
  /** Toolbar content on the left (e.g. attach button). */
  leftActions?: React.ReactNode;
  /** Toolbar content on the right of the input, before the send button (e.g. model picker, mic). */
  rightActions?: React.ReactNode;
  /** Show the agent as busy — swaps send for a stop button. */
  loading?: boolean;
  onStop?: () => void;
  /** Max auto-grow height in px. */
  maxHeight?: number;
  /** Disable input + send. */
  disabled?: boolean;
}

export interface AgentStepProps
  extends Omit<React.LiHTMLAttributes<HTMLLIElement>, "title"> {
  /** Execution status of the step. */
  status?: AgentStepStatus;
  /** Action-type icon (e.g. read, execute, search). Overrides the status glyph. */
  icon?: React.ReactNode;
  /** Step label. */
  title: React.ReactNode;
  /** Supporting detail under the title. */
  description?: React.ReactNode;
  /** Optional progress track, 0–100, shown under the step while active. */
  progress?: number;
}

export interface AiDisclosureProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Presentation: inline `pill`, corner `badge`, or full-width `banner`. */
  variant?: AiDisclosureVariant;
  /** Leading icon. Defaults to a sparkle. */
  icon?: React.ReactNode;
  /** Label / message. Ignored if `children` is provided. Has a per-variant default. */
  label?: React.ReactNode;
}

export interface AiCaveatProps extends React.HTMLAttributes<HTMLParagraphElement> {
  /** Leading icon. Defaults to an info glyph. Pass `null` to omit. */
  icon?: React.ReactNode;
}

export interface AlertProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  variant?: AlertVariant;
  /** Optional bold title above the body. */
  title?: React.ReactNode;
  /** Custom icon; defaults to a variant-appropriate one. */
  icon?: React.ReactNode;
  /** Hide the leading icon entirely. */
  hideIcon?: boolean;
}

export interface AlertDialogProps {
  /** Whether the alert dialog is open. */
  open: boolean;
  /** Called when the dialog requests to close (Escape / a button). */
  onOpenChange: (open: boolean) => void;
  title: React.ReactNode;
  description?: React.ReactNode;
  /** Confirm button label. */
  confirmLabel?: string;
  /** Cancel button label. */
  cancelLabel?: string;
  onConfirm?: () => void;
  onCancel?: () => void;
  /** Style the confirm action as destructive. */
  destructive?: boolean;
  /** Extra content between the description and the actions. */
  children?: React.ReactNode;
  className?: string;
}

export interface AspectRatioProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Width / height ratio (e.g. 16/9). Defaults to 1 (square). */
  ratio?: number;
}

export interface AttachmentTileProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  /** File or attachment name. */
  name: React.ReactNode;
  /** Metadata line, e.g. `"PDF · 240 KB"`. */
  meta?: React.ReactNode;
  /** Image URL — renders a thumbnail tile instead of a document chip. */
  thumbnail?: string;
  /** Doctype icon for the document chip. Defaults to a document glyph. */
  icon?: React.ReactNode;
  /** Called when the remove control is used. Hidden if omitted. */
  onRemove?: () => void;
}

export interface AudioMessageProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Whether audio is currently playing (controls the play/pause glyph + animation). */
  playing?: boolean;
  /** Duration or elapsed label, e.g. `"0:42"`. */
  duration?: React.ReactNode;
  /** Transcript excerpt shown below the player. */
  transcript?: React.ReactNode;
  /** Called when the play/pause control is used. */
  onPlayToggle?: () => void;
}

export interface AvatarProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Role used to pick a default icon and styling when no image/initials given. */
  role?: MessageRole;
  /** Optional image URL; takes precedence over initials and the role icon. */
  src?: string;
  /** Explicit initials. If omitted, derived from `name`. */
  initials?: string;
  /** Display name — used to derive initials and the default aria-label. */
  name?: string;
  /** Corner style. `rounded` suits entity/person avatars, `circle` suits chat. */
  shape?: "circle" | "rounded";
  /** Accessible label / alt text. */
  alt?: string;
}

export interface BadgeProps extends React.HTMLAttributes<HTMLSpanElement> {
  /** Visual style. */
  variant?: BadgeVariant;
  /** Optional icon rendered before the label. */
  icon?: React.ReactNode;
}

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: ButtonVariant;
  size?: ButtonSize;
  /** Icon rendered before the label. */
  leftIcon?: React.ReactNode;
  /** Icon rendered after the label. */
  rightIcon?: React.ReactNode;
}

export interface CapabilityOverviewProps extends React.HTMLAttributes<HTMLDivElement> {
  /** The columns to show — typically Examples / Capabilities / Limits. */
  sections: CapabilitySection[];
  /** Heading above the columns. */
  heading?: React.ReactNode;
  /** Footnote, e.g. a knowledge-cutoff note. */
  footnote?: React.ReactNode;
}

export interface CarouselProps extends React.HTMLAttributes<HTMLDivElement> {
  orientation?: Orientation;
  opts?: EmblaOptionsType;
  /** Receive the Embla API instance once ready. */
  setApi?: (api: EmblaCarouselType | undefined) => void;
}

export interface ChartContainerProps extends React.HTMLAttributes<HTMLDivElement> {
  config: ChartConfig;
  /** A single recharts chart element (BarChart, LineChart, …). */
  children: React.ReactElement;
}

export interface ChartTooltipContentProps {
  active?: boolean;
  payload?: TooltipPayloadItem[];
  label?: React.ReactNode;
  config?: ChartConfig;
}

export interface ChartLegendContentProps {
  payload?: LegendPayloadItem[];
  config?: ChartConfig;
}

export interface CheckboxProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "onChange" | "value" | "type"> {
  /** Controlled checked state. */
  checked?: boolean;
  /** Initial state when uncontrolled. */
  defaultChecked?: boolean;
  /** Called with the next checked state. */
  onCheckedChange?: (checked: boolean) => void;
}

export interface ChecklistItemProps extends Omit<React.LiHTMLAttributes<HTMLLIElement>, "title"> {
  /** Whether the step is completed (shows a filled check + strikes the title). */
  done?: boolean;
  /** Step title. */
  title: React.ReactNode;
  /** Supporting description. */
  description?: React.ReactNode;
  /** Trailing action, e.g. a <Button>Connect</Button>. */
  action?: React.ReactNode;
}

export interface ChecklistProps extends React.HTMLAttributes<HTMLUListElement> {
  /** Show hairline dividers between items. */
  divided?: boolean;
}

export interface ChipProps extends React.HTMLAttributes<HTMLSpanElement> {
  /** Show a leading status dot. Pass a className to color it (e.g. "bg-success"). */
  dot?: boolean;
  /** Tailwind classes controlling the dot color (defaults to muted). */
  dotClassName?: string;
  /** When provided, renders a trailing remove button that calls this handler. */
  onRemove?: () => void;
  /** Accessible label for the remove button. */
  removeLabel?: string;
}

export interface CitationProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "title"> {
  /** Source index shown in the chip, e.g. `4`. Ignored if `children` is given. */
  index?: number;
  /** Text label instead of a number, e.g. `"wikipedia.com"`. */
  label?: React.ReactNode;
}

export interface SourceItemProps
  extends Omit<React.LiHTMLAttributes<HTMLLIElement>, "title"> {
  /** Optional leading index, e.g. `1`. */
  index?: number;
  /** Icon shown in the leading slot. Defaults to a document icon. */
  icon?: React.ReactNode;
  /** Source title, e.g. a filename. */
  title: React.ReactNode;
  /** Metadata line, e.g. `"Source · PDF · Section 4.1"`. */
  meta?: React.ReactNode;
  /** If set, the open affordance becomes a link to this href. */
  href?: string;
  /** Label for the open affordance. Defaults to `"Open"`. */
  actionLabel?: React.ReactNode;
  /** Called when the open affordance is activated (button mode). */
  onOpen?: () => void;
}

export interface SourceListProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Heading above the list, e.g. `"3 sources · 1 missing policy"`. */
  heading?: React.ReactNode;
}

export interface CodeBlockProps extends React.HTMLAttributes<HTMLDivElement> {
  /** The raw source code to display. */
  code: string;
  /** Language label shown in the header (e.g. "ts", "python"). */
  language?: string;
  /** Hide the copy button. */
  hideCopy?: boolean;
}

export interface CollapsibleProps extends React.HTMLAttributes<HTMLDivElement> {
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  disabled?: boolean;
}

export interface CollapsibleTriggerProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** Hide the default chevron affordance. */
  hideChevron?: boolean;
}

export interface ComboboxProps {
  options: ComboboxOption[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  placeholder?: string;
  searchPlaceholder?: string;
  emptyText?: string;
  disabled?: boolean;
  className?: string;
  /** Accessible name for the trigger. */
  "aria-label"?: string;
}

export interface CommandGroupProps extends React.HTMLAttributes<HTMLDivElement> {
  heading?: React.ReactNode;
}

export interface CommandItemProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onSelect"> {
  /** The value used for filtering + selection. Defaults to the text content. */
  value: string;
  disabled?: boolean;
  onSelect?: (value: string) => void;
}

export interface ConfidenceIndicatorProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Confidence score, 0–100. */
  value: number;
  /** Label above the meter. Defaults to `"Confidence"`. */
  label?: React.ReactNode;
  /** Score below which the agent should defer to a human. Defaults to 70. */
  threshold?: number;
  /** Explanatory note shown under the meter (e.g. a review recommendation). */
  note?: React.ReactNode;
  /** Force a level instead of deriving it from `value`/`threshold`. */
  level?: ConfidenceLevel;
}

export interface ConnectorCardProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  /** Connector name, e.g. `"GitHub"`. */
  name: React.ReactNode;
  /** What the connector gives the agent access to. */
  description?: React.ReactNode;
  /** Connector logo/icon. Defaults to a plug glyph. */
  icon?: React.ReactNode;
  /** Whether the connector is already connected. */
  connected?: boolean;
  /** Called to connect. Renders the connect button when set and not connected. */
  onConnect?: () => void;
  /** Called to disconnect. Renders a manage/disconnect control when connected. */
  onDisconnect?: () => void;
  connectLabel?: React.ReactNode;
  disconnectLabel?: React.ReactNode;
}

export interface ContextMenuProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "content"> {
  /** Menu items — compose ContextMenuItem / ContextMenuSeparator / ContextMenuLabel. */
  content: React.ReactNode;
  /** The area that opens the menu on right-click. */
  children: React.ReactNode;
}

export interface ContextMenuItemProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  icon?: React.ReactNode;
  trailing?: React.ReactNode;
  destructive?: boolean;
}

export interface DataTableProps<TData, TValue> {
  columns: ColumnDef<TData, TValue>[];
  data: TData[];
  /** Rows per page. Set 0 to disable pagination. */
  pageSize?: number;
  /** Message shown when there are no rows. */
  emptyMessage?: React.ReactNode;
  className?: string;
}

export interface DatePickerProps {
  value?: Date;
  defaultValue?: Date;
  onValueChange?: (date: Date | undefined) => void;
  placeholder?: string;
  disabled?: boolean;
  /** Disable individual days. */
  isDateDisabled?: (date: Date) => boolean;
  className?: string;
  "aria-label"?: string;
}

export interface DialogProps {
  /** Whether the dialog is open. */
  open: boolean;
  /** Called when the dialog requests to close (overlay click / Escape). */
  onOpenChange: (open: boolean) => void;
  /** Panel content — compose DialogHeader/Title/Description/Footer. */
  children: React.ReactNode;
  /** Class overrides for the panel. */
  className?: string;
  /** Disable closing on overlay click / Escape. */
  dismissible?: boolean;
}

export interface ErrorStateProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  /** `empty` for neutral empty states, `error` for a failure (tints the icon). */
  variant?: ErrorStateVariant;
  /** Icon shown above the title. */
  icon?: React.ReactNode;
  /** Headline, e.g. `"Something went wrong"`. */
  title: React.ReactNode;
  /** Supporting explanation. */
  description?: React.ReactNode;
  /** Action buttons, e.g. Retry / Edit prompt. */
  actions?: React.ReactNode;
}

export interface FollowUpProps extends React.HTMLAttributes<HTMLDivElement> {
  /** The AI answer text. Ignored if `children` is provided. */
  answer?: React.ReactNode;
  /** The stated assumption; rendered as an editable chip. */
  assumption?: FollowUpAssumption;
  /** Called when the assumption chip is activated (to change the assumption). */
  onChangeAssumption?: () => void;
}

export interface GettingStartedPillProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "title"> {
  /** Leading label. */
  label?: React.ReactNode;
  /** Leading icon (defaults to a rocket). */
  icon?: React.ReactNode;
  /** Completed step count — combined with `total` to render "current of total". */
  current?: number;
  /** Total step count. */
  total?: number;
  /** Override the rendered progress text (takes precedence over current/total). */
  progressLabel?: React.ReactNode;
  /** Whether the associated panel is expanded — flips the chevron. */
  open?: boolean;
}

export interface GlobalNavProps extends React.HTMLAttributes<HTMLElement> {
  /** Leading content — brand mark, page heading, breadcrumbs. */
  left?: React.ReactNode;
  /** Centered content — typically a search field. */
  center?: React.ReactNode;
  /** Trailing content — notifications, account avatar, actions. */
  right?: React.ReactNode;
}

export interface HoverCardProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "content"> {
  /** The element that reveals the card on hover/focus. */
  trigger: React.ReactNode;
  /** The floating card content. */
  content: React.ReactNode;
  side?: "top" | "bottom";
  align?: "start" | "center" | "end";
  /** Delay in ms before opening on hover. */
  openDelay?: number;
  /** Delay in ms before closing after leaving. */
  closeDelay?: number;
}

export interface IconButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** Accessible label — required since the button has no visible text. */
  "aria-label": string;
  variant?: IconButtonVariant;
  size?: IconButtonSize;
}

export interface InlineFeedbackProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange"> {
  /** Current rating (controlled). */
  rating?: FeedbackRating | null;
  /** Initial rating (uncontrolled). */
  defaultRating?: FeedbackRating | null;
  /** Called when the user rates the response. */
  onRate?: (rating: FeedbackRating) => void;
  /** Called when the copy control is used. Hidden if omitted. */
  onCopy?: () => void;
  /** Called when the regenerate control is used. Hidden if omitted. */
  onRegenerate?: () => void;
  /** Called when the more-actions control is used. Hidden if omitted. */
  onMore?: () => void;
}

export interface InputProps extends React.InputHTMLAttributes<HTMLInputElement> {
  /** Render an error ring and set `aria-invalid`. */
  invalid?: boolean;
}

export interface InputBarProps
  extends Omit<React.TextareaHTMLAttributes<HTMLTextAreaElement>, "onSubmit" | "value" | "onChange"> {
  /** Controlled value of the input. */
  value: string;
  /** Called when the value changes. */
  onValueChange: (value: string) => void;
  /** Called with the trimmed value on submit (Enter or button). */
  onSubmit: (value: string) => void;
  /** Show the agent as busy — swaps the send button for a stop button. */
  loading?: boolean;
  /** Called when the stop button is pressed while `loading`. */
  onStop?: () => void;
  /** Max auto-grow height in px before scrolling. */
  maxHeight?: number;
}

export interface InputOtpProps {
  /** Number of code cells. */
  length?: number;
  value?: string;
  defaultValue?: string;
  onChange?: (value: string) => void;
  /** Fired once every cell is filled. */
  onComplete?: (value: string) => void;
  disabled?: boolean;
  /** Only accept digits (default true). */
  numeric?: boolean;
  className?: string;
  "aria-label"?: string;
}

export interface KnowledgeBasePickerProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange"> {
  /** The available knowledge sources. */
  sources: KnowledgeSource[];
  /** Selected source ids (controlled). */
  value?: string[];
  /** Initial selection (uncontrolled). */
  defaultValue?: string[];
  /** Called when the selection changes. */
  onValueChange?: (ids: string[]) => void;
  /** Heading above the list. Defaults to `"Knowledge sources"`. */
  heading?: React.ReactNode;
}

export interface LabelProps extends React.LabelHTMLAttributes<HTMLLabelElement> {
  /** Show a destructive-colored asterisk to mark the field required. */
  required?: boolean;
}

export interface LinkButtonProps extends React.AnchorHTMLAttributes<HTMLAnchorElement> {
  /** Icon before the label. */
  leftIcon?: React.ReactNode;
  /** Icon after the label (e.g. an arrow for "Learn More"). */
  rightIcon?: React.ReactNode;
}

export interface Md3ActionPlanStepProps
  extends Omit<React.LiHTMLAttributes<HTMLLIElement>, "title"> {
  /** Step title. */
  title: React.ReactNode;
  /** Supporting detail under the title. */
  description?: React.ReactNode;
}

export interface Md3ActionPlanProps extends React.HTMLAttributes<HTMLDivElement> {
  heading?: React.ReactNode;
  description?: React.ReactNode;
  onAccept?: () => void;
  onEdit?: () => void;
  onReject?: () => void;
  acceptLabel?: React.ReactNode;
  editLabel?: React.ReactNode;
  rejectLabel?: React.ReactNode;
}

export interface Md3AgentComposerProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onSubmit"> {
  value: string;
  onValueChange: (value: string) => void;
  onSubmit: (value: string) => void;
  placeholder?: string;
  leftActions?: React.ReactNode;
  rightActions?: React.ReactNode;
  loading?: boolean;
  onStop?: () => void;
  maxHeight?: number;
  disabled?: boolean;
}

export interface Md3BadgeProps extends Omit<React.HTMLAttributes<HTMLSpanElement>, "content"> {
  /** Numeric/text count. Omit for a small dot badge. */
  content?: React.ReactNode;
  /** Clamp numeric content, e.g. max=99 renders "99+". */
  max?: number;
  /** The element the badge is attached to (badge floats at its top-right). */
  children?: React.ReactNode;
}

export interface Md3BannerProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Leading icon. */
  icon?: React.ReactNode;
  /** Trailing action buttons (typically text buttons). */
  actions?: React.ReactNode;
}

export interface Md3BottomSheetProps extends React.HTMLAttributes<HTMLDivElement> {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** Show the drag handle at the top (default true). */
  showHandle?: boolean;
  dismissible?: boolean;
}

export interface Md3ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: Md3ButtonVariant;
  /** Leading icon element. */
  icon?: React.ReactNode;
}

export interface Md3CardProps extends React.HTMLAttributes<HTMLDivElement> {
  variant?: Md3CardVariant;
  /** Add hover/press state layer + pointer cursor (for actionable cards). */
  interactive?: boolean;
}

export interface Md3CheckboxProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "onChange" | "type"> {
  checked?: boolean;
  defaultChecked?: boolean;
  indeterminate?: boolean;
  onCheckedChange?: (checked: boolean) => void;
}

export interface Md3ChipProps extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "onSelect"> {
  variant?: Md3ChipVariant;
  /** Filter chips: selected state (shows a leading check). */
  selected?: boolean;
  /** Leading icon (assist/input/suggestion). */
  icon?: React.ReactNode;
  /** Input chips: renders a trailing remove button and fires this on click. */
  onRemove?: () => void;
}

export interface Md3DatePickerProps {
  value?: Date;
  defaultValue?: Date;
  onValueChange?: (date: Date | undefined) => void;
  label?: string;
  disabled?: boolean;
  className?: string;
  "aria-label"?: string;
}

export interface Md3DialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  headline: React.ReactNode;
  /** Optional hero icon, centered above the headline. */
  icon?: React.ReactNode;
  /** Supporting body content. */
  children?: React.ReactNode;
  /** Action buttons (typically text buttons), right-aligned. */
  actions?: React.ReactNode;
  /** Close on scrim click / Escape (default true). */
  dismissible?: boolean;
  className?: string;
}

export interface Md3DividerProps extends React.HTMLAttributes<HTMLDivElement> {
  orientation?: "horizontal" | "vertical";
  /** Inset the divider (e.g. to align with list text). */
  inset?: boolean;
}

export interface Md3FabProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  size?: Md3FabSize;
  color?: Md3FabColor;
  icon: React.ReactNode;
}

export interface Md3IconButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: Md3IconButtonVariant;
  /** Toggle-selected state (affects filled/tonal background). */
  selected?: boolean;
  /** Required for icon-only buttons. */
  "aria-label": string;
}

export interface Md3ListItemProps extends React.HTMLAttributes<HTMLDivElement> {
  headline: React.ReactNode;
  supportingText?: React.ReactNode;
  leading?: React.ReactNode;
  trailing?: React.ReactNode;
  /** Add a hover/press state layer + role="button" for actionable rows. */
  interactive?: boolean;
}

export interface Md3MenuItemProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  icon?: React.ReactNode;
  /** Trailing content — a shortcut hint or submenu marker. */
  trailing?: React.ReactNode;
}

export interface Md3MessageProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Who authored the message. */
  role: MessageRole;
  /** Message text. Ignored if `children` is provided. */
  content?: string;
  /** True while the assistant is still streaming this message. */
  streaming?: boolean;
  /** Hide the avatar (e.g. for consecutive same-role messages). */
  hideAvatar?: boolean;
  /** Custom node rendered in place of the default avatar. */
  avatar?: React.ReactNode;
}

export interface Md3NavigationBarProps
  extends Omit<React.HTMLAttributes<HTMLElement>, "defaultValue"> {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
}

export interface Md3NavigationBarItemProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
